// Bitmap fonts for the Text tool (data generated by tools/fontgen.py).
// SPDX-License-Identifier: MIT (code); font data licenses in docs/FONTS.md
#pragma once
#include <stdint.h>

typedef struct {
	const char* name;
	uint8_t height;          // rows per glyph
	const uint8_t* advance;  // 95 entries (chars 32..126): pixels to the next character
	const uint8_t* rows;     // 95 * height bytes; bit 7 = leftmost pixel
} PixFont;

#define FONT_COUNT 6
extern const PixFont FONTS[FONT_COUNT];
